package uz.mirix.tracelens.internal;import org.junit.jupiter.api.Test;import uz.mirix.tracelens.*;import java.time.Instant;import java.util.*;import static org.assertj.core.api.Assertions.assertThat;class ServerTimingFormatterTest{@Test void emitsBrowserCompatibleMetrics(){TraceReport r=new TraceReport("abc",Instant.now(),"GET","/api/orders/{id}",200,20_000_000,List.of(new TraceSpan(TraceCategory.SQL,"SQL SELECT: select * from orders where id = ?",0,3_000_000,Map.of()),new TraceSpan(TraceCategory.HTTP,"HTTP GET inventory-service",4_000_000,8_000_000,Map.of())),null,false);String h=ServerTimingFormatter.format(r,new TraceLensProperties());assertThat(h).contains("sql-1;dur=3.00").contains("http-2;dur=8.00").contains("total;dur=20.00");}}
